import type { ChapterBundle } from '@/types/content'

export default JSON.parse(
  "{\n  \"workId\": \"han-fei-zi\",\n  \"chapter\": {\n    \"id\": \"han-fei-zi_ch-45\",\n    \"workId\": \"han-fei-zi\",\n    \"order\": 45,\n    \"title\": \"六反\",\n    \"difficulty\": 4,\n    \"estimatedMinutes\": 10,\n    \"passageIds\": [\n      \"han-fei-zi_ch-45_p-1\",\n      \"han-fei-zi_ch-45_p-2\",\n      \"han-fei-zi_ch-45_p-3\",\n      \"han-fei-zi_ch-45_p-4\",\n      \"han-fei-zi_ch-45_p-5\",\n      \"han-fei-zi_ch-45_p-6\",\n      \"han-fei-zi_ch-45_p-7\",\n      \"han-fei-zi_ch-45_p-8\"\n    ],\n    \"tags\": [\n      \"法家\",\n      \"帝王術\",\n      \"法術勢\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"order\": 1,\n      \"canonicalText\": \"畏死難，降北之民也，而世尊之曰貴生之士；學道立方，離法之民也，而世尊之曰文學之士；遊居厚養，牟食之民也，而世尊之曰有能之士；語曲牟知，偽詐之民也，而世尊之曰辯智之士；行劍攻殺，暴憿之民也，而世尊之曰磏勇之士；活湧匿姦，當死之民也，而世尊之曰任譽之士；此六民者，世之所譽也。赴險殉誠，死節之民，而世少之曰失計之民也；寡聞從令，全法之民也，而世少之曰樸陋之民也；力作而食，生利之民也，而世少之曰寡能之民也；嘉厚純粹，整穀之民也，而世少之曰愚戇之民也；重命畏事，尊上之民也，而世少之曰怯懾之民也；挫賊遏姦，明上之民也，而世少之曰諂讒之民也；此六民者，世之所毀也。姦偽無益之民六，而世譽之如彼；耕戰有益之民六，而世毀之如此；此之謂六反。布衣循私利而譽之，世主聽虛聲而禮之，禮之所在，利必加焉。百姓循私害而訾之，世主壅於俗而賤之，賤之所在，害必加焉。故名賞在乎私惡當罪之民，而毀害在乎公善宜賞之士，索國之富強，不可得也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-45_p-1_s-1\",\n        \"han-fei-zi_ch-45_p-1_s-2\",\n        \"han-fei-zi_ch-45_p-1_s-3\",\n        \"han-fei-zi_ch-45_p-1_s-4\",\n        \"han-fei-zi_ch-45_p-1_s-5\",\n        \"han-fei-zi_ch-45_p-1_s-6\",\n        \"han-fei-zi_ch-45_p-1_s-7\",\n        \"han-fei-zi_ch-45_p-1_s-8\",\n        \"han-fei-zi_ch-45_p-1_s-9\",\n        \"han-fei-zi_ch-45_p-1_s-10\",\n        \"han-fei-zi_ch-45_p-1_s-11\",\n        \"han-fei-zi_ch-45_p-1_s-12\",\n        \"han-fei-zi_ch-45_p-1_s-13\",\n        \"han-fei-zi_ch-45_p-1_s-14\",\n        \"han-fei-zi_ch-45_p-1_s-15\",\n        \"han-fei-zi_ch-45_p-1_s-16\",\n        \"han-fei-zi_ch-45_p-1_s-17\",\n        \"han-fei-zi_ch-45_p-1_s-18\",\n        \"han-fei-zi_ch-45_p-1_s-19\",\n        \"han-fei-zi_ch-45_p-1_s-20\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"畏死難，降北的民啊，而且世尊的說道：貴生的士；學道立方，離法規法令的民啊，而且世尊的說道：文學的士；遊居厚養，牟食的民啊，而且世尊的說道：有能的士；語曲牟知，偽詐的民啊，而且世尊的說道：辯智的士；行劍攻殺，暴憿的民啊，而且世尊的說道：磏勇的士；活湧匿姦，當死的民啊，而且世尊的說道：任譽的士；此六民的人或事，世的所譽啊。赴險殉誠，死節的民，而且世少的說道：失計的民啊；寡聞從令，全法規法令的民啊，而且世少的說道：樸陋的民啊；力作而且食，生利的民啊，而且世少的說道：寡能的民啊；嘉厚純粹，整穀的民啊，而且世少的說道：愚戇的民啊；重命畏事，尊上的民啊，而且世少的說道：怯懾的民啊；挫賊遏姦，明上的民啊，而且世少的說道：諂讒的民啊；此六民的人或事，世的所毀啊。姦偽無益的民六，而且世譽的如彼；耕戰有益的民六，而且世毀的如此；此的謂六反。布衣循私利而且譽的，世主聽虛聲而且禮的，禮的所在，利必加焉。百姓循私害而且訾的，世主壅於俗而且賤的，賤的所在，害必加焉。所以名賞賜在乎私惡當罪的民，而且毀害在乎公善宜賞賜的士，索國的富強，不可得啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈六反〉。韓非深刻融合法、術、勢三大治國精要，此處「畏死難，降北之民也，而世尊之曰貴生之士」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「畏」、「死」、「難」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「畏死難降北之民也而世尊之曰貴生之士學道立方離法之」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「學道立方，離法之民也，而世尊之曰文學之士」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-2\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"order\": 2,\n      \"canonicalText\": \"古者有諺曰：「為政、猶沐也，雖有棄髮、必為之。」愛棄髮之費，而忘長髮之利，不知權者也。夫彈痤者痛，飲藥者苦，為苦憊之故，不彈痤、飲藥，則身不活、病不已矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-45_p-2_s-1\",\n        \"han-fei-zi_ch-45_p-2_s-2\",\n        \"han-fei-zi_ch-45_p-2_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"古的人或事有諺說道：為政、猶沐啊，雖有棄髮、必為的。愛棄髮的費，而且忘長髮的利，不知權的人或事啊。夫彈痤的人或事痛，飲藥的人或事苦，為苦憊的所以，不彈痤、飲藥，則身不活、病不已矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈六反〉。韓非深刻融合法、術、勢三大治國精要，此處「古者有諺曰：「為政、猶沐也，雖有棄髮、必為之」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「古」、「有」、「諺」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「古者有諺曰為政猶沐也雖有棄髮必為之愛棄髮之費而忘」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」愛棄髮之費，而忘長髮之利，不知權者也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-3\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"order\": 3,\n      \"canonicalText\": \"今上下之接，無子父之澤，而欲以行義禁下，則交必有郤矣。且父母之於子也，產男則相賀，產女則殺之。此俱出父母之懷衽，然男子受賀，女子殺之者，慮其後便、計之長利也。故父母之於子也，猶用計算之心以相待也，而況無父子之澤乎！\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-45_p-3_s-1\",\n        \"han-fei-zi_ch-45_p-3_s-2\",\n        \"han-fei-zi_ch-45_p-3_s-3\",\n        \"han-fei-zi_ch-45_p-3_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今上下的接，無子父的澤，而且欲以行義禁下，則交必有郤矣。且父母的於子啊，產男則相賀，產女則殺的。此俱出父母的懷衽，然男子受賀，女子殺的的人或事，慮他的後便、計的長利啊。所以父母的於子啊，猶用計算的心以相待啊，而且況無父子的澤乎！\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈六反〉。韓非深刻融合法、術、勢三大治國精要，此處「今上下之接，無子父之澤，而欲以行義禁下，則交必有郤矣」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「今」、「上」、「下」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「今上下之接無子父之澤而欲以行義禁下則交必有郤矣且」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「且父母之於子也，產男則相賀，產女則殺之」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-4\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"order\": 4,\n      \"canonicalText\": \"今學者之說人主也，皆去求利之心，出相愛之道，是求人主之過父母之親也，此不熟於論恩詐而誣也，故明主不受也。聖人之治也，審於法禁，法禁明著則官法；必於賞罰，賞罰不阿則民用。官官治則國富，國富則兵強，而霸王之業成矣。霸王者，人主之大利也。人主挾大利以聽治，故其任官者當能，其賞罰無私。使士民明焉盡力致死、則功伐可立而爵祿可致，爵祿致而富貴之業成矣。富貴者，人臣之大利也。人臣挾大利以從事，故其行危至死，其力盡而不望。此謂君不仁，臣不忠，則不可以霸王矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-45_p-4_s-1\",\n        \"han-fei-zi_ch-45_p-4_s-2\",\n        \"han-fei-zi_ch-45_p-4_s-3\",\n        \"han-fei-zi_ch-45_p-4_s-4\",\n        \"han-fei-zi_ch-45_p-4_s-5\",\n        \"han-fei-zi_ch-45_p-4_s-6\",\n        \"han-fei-zi_ch-45_p-4_s-7\",\n        \"han-fei-zi_ch-45_p-4_s-8\",\n        \"han-fei-zi_ch-45_p-4_s-9\",\n        \"han-fei-zi_ch-45_p-4_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今學的人或事的說人主啊，皆去求利的心，出相愛的道，是求人主的過父母的親啊，此不熟於論恩詐而且誣啊，所以明主不受啊。聖人的治啊，審於法規法令禁，法規法令禁明著則官法規法令；必於賞賜與刑罰，賞賜與刑罰不阿則民用。官官治則國富，國富則兵強，而且霸王的業成矣。霸王的人或事，人主的大利啊。人主挾大利以聽治，所以他的任官的人或事當能，他的賞賜與刑罰無私。使士民明焉盡力致死、則功伐可立而且爵祿可致，爵祿致而且富貴的業成矣。富貴的人或事，人臣屬的大利啊。人臣屬挾大利以從事，所以他的行危至死，他的力盡而且不望。此謂國君不仁，臣屬不忠，則不可以霸王矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈六反〉。韓非深刻融合法、術、勢三大治國精要，此處「今學者之說人主也，皆去求利之心，出相愛之道，是求人主之過父母之親也，此不熟於論恩詐而誣也，故明主不受也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「今」、「學」、「說」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「今學者之說人主也皆去求利之心出相愛之道是求人主之」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「聖人之治也，審於法禁，法禁明著則官法」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-5\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"order\": 5,\n      \"canonicalText\": \"夫姦必知則備，必誅則止；不知則肆，不誅則行。夫陳輕貨於幽隱，雖曾、史可疑也；懸百金於市，雖大盜不取也。不知則曾、史可疑於幽隱，必知則大盜不取懸金於市。故明主之治國也眾其守、而重其罪，使民以法禁而不以廉止。母之愛子也倍父，父令之行於子者十母；吏之於民無愛，令之行於民也萬父。母積愛而令窮，吏用威嚴而民聽從，嚴愛之筴亦可決矣。且父母之所以求於子也，動作則欲其安利也，行身則欲其遠罪也；君上之於民也，有難則用其死，安平則盡其力。親以厚愛關子於安利而不聽，君以無愛利求民之死力而令行。明主知之，故不養恩愛之心而增威嚴之勢。故母厚愛處，子多敗，推愛也；父薄愛教笞，子多善，用嚴也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-45_p-5_s-1\",\n        \"han-fei-zi_ch-45_p-5_s-2\",\n        \"han-fei-zi_ch-45_p-5_s-3\",\n        \"han-fei-zi_ch-45_p-5_s-4\",\n        \"han-fei-zi_ch-45_p-5_s-5\",\n        \"han-fei-zi_ch-45_p-5_s-6\",\n        \"han-fei-zi_ch-45_p-5_s-7\",\n        \"han-fei-zi_ch-45_p-5_s-8\",\n        \"han-fei-zi_ch-45_p-5_s-9\",\n        \"han-fei-zi_ch-45_p-5_s-10\",\n        \"han-fei-zi_ch-45_p-5_s-11\",\n        \"han-fei-zi_ch-45_p-5_s-12\",\n        \"han-fei-zi_ch-45_p-5_s-13\",\n        \"han-fei-zi_ch-45_p-5_s-14\",\n        \"han-fei-zi_ch-45_p-5_s-15\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"夫姦必知則備，必誅則止；不知則肆，不誅則行。夫陳輕貨於幽隱，雖曾、史可疑啊；懸百金於市，雖大盜不取啊。不知則曾、史可疑於幽隱，必知則大盜不取懸金於市。所以明主的治國啊眾他的守、而且重他的罪，使民以法規法令禁而且不以廉止。母的愛子啊倍父，父令的行於子的人或事十母；吏的於民無愛，令的行於民啊萬父。母積愛而且令窮，吏用威嚴而且民聽從，嚴愛的筴亦可決矣。且父母的所以求於子啊，動作則欲他的安利啊，行身則欲他的遠罪啊；國君上的於民啊，有難則用他的死，安平則盡他的力。親以厚愛關子於安利而且不聽，國君以無愛利求民的死力而且令行。明主知的，所以不養恩愛的心而且增威嚴的權位威勢。所以母厚愛處，子多敗，推愛啊；父薄愛教笞，子多善，用嚴啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈六反〉。韓非深刻融合法、術、勢三大治國精要，此處「夫姦必知則備，必誅則止」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「姦」、「必」、「知」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「夫姦必知則備必誅則止不知則肆不誅則行夫陳輕貨於幽」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「不知則肆，不誅則行」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"order\": 6,\n      \"canonicalText\": \"今家人之治產也，相忍以飢寒，相強以勞苦，雖犯軍旅之難，饑饉之患，溫衣美食者，必是家也；相憐以衣食，相惠以佚樂，天饑歲荒，嫁妻賣子者，必是家也。故法之為道，前苦而長利；仁之為道，偷樂而後窮。聖人權其輕重，出其大利，故用法之相忍，而棄仁人之相憐也。學者之言，皆曰輕刑，此亂亡之術也。凡賞罰之必者，勸禁也。賞厚、則所欲之得也疾，罰重、則所惠之禁也急。夫欲利者必惡害，害者，利之反也，反於所欲，焉得無惡。欲治者必惡亂，亂者，治之反也。是故欲治甚者，其賞必厚矣；其惡亂甚者，其罰必重矣。今取於輕刑者，其惡亂不甚也，其欲治又不甚也，此非特無術也，又乃無行。是故決賢不肖愚知之美，在賞罰之輕重。且夫重刑者，非為罪人也。明主之法，揆也。治賊，非治所揆也；治所揆也者，是治死人也。刑盜，非治所刑也；治所刑也者，是治胥靡也。故曰重一姦之罪而止境內之邪，此所以為治也。重罰者，盜賊也；而悼懼者，良民也；欲治者奚疑於重刑！若夫厚賞者，非獨賞功也，又勸一國。受賞者甘利，未賞者慕業，是報一人之功而勸境內之眾也，欲治者何疑於厚賞！今不知治者，皆曰重刑傷民，輕刑可以止姦，何必於重哉？此不察於治者也。夫以重止者，未必以輕止也；以輕止者，必以重止矣。是以上設重刑者而姦盡止，姦盡止則此奚傷於民也？所謂重刑者，姦之所利者細，而上之所加焉者大也；民不以小利蒙大罪，故姦必止者也。所謂輕刑者，姦之所利者大，上之所加焉者小也；民慕其利而傲其罪，故姦不止也。故先聖有諺曰：「不躓於山，而躓於垤。」山者大、故人順之，垤微小、故人易之也。今輕刑罰，民必易之。犯而不誅，是驅國而棄之也；犯而誅之，是為民設陷也。是故輕罪者，民之垤也。是以輕罪之為民道也，非亂國也則設民陷也，此則可謂傷民矣！\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-45_p-6_s-1\",\n        \"han-fei-zi_ch-45_p-6_s-2\",\n        \"han-fei-zi_ch-45_p-6_s-3\",\n        \"han-fei-zi_ch-45_p-6_s-4\",\n        \"han-fei-zi_ch-45_p-6_s-5\",\n        \"han-fei-zi_ch-45_p-6_s-6\",\n        \"han-fei-zi_ch-45_p-6_s-7\",\n        \"han-fei-zi_ch-45_p-6_s-8\",\n        \"han-fei-zi_ch-45_p-6_s-9\",\n        \"han-fei-zi_ch-45_p-6_s-10\",\n        \"han-fei-zi_ch-45_p-6_s-11\",\n        \"han-fei-zi_ch-45_p-6_s-12\",\n        \"han-fei-zi_ch-45_p-6_s-13\",\n        \"han-fei-zi_ch-45_p-6_s-14\",\n        \"han-fei-zi_ch-45_p-6_s-15\",\n        \"han-fei-zi_ch-45_p-6_s-16\",\n        \"han-fei-zi_ch-45_p-6_s-17\",\n        \"han-fei-zi_ch-45_p-6_s-18\",\n        \"han-fei-zi_ch-45_p-6_s-19\",\n        \"han-fei-zi_ch-45_p-6_s-20\",\n        \"han-fei-zi_ch-45_p-6_s-21\",\n        \"han-fei-zi_ch-45_p-6_s-22\",\n        \"han-fei-zi_ch-45_p-6_s-23\",\n        \"han-fei-zi_ch-45_p-6_s-24\",\n        \"han-fei-zi_ch-45_p-6_s-25\",\n        \"han-fei-zi_ch-45_p-6_s-26\",\n        \"han-fei-zi_ch-45_p-6_s-27\",\n        \"han-fei-zi_ch-45_p-6_s-28\",\n        \"han-fei-zi_ch-45_p-6_s-29\",\n        \"han-fei-zi_ch-45_p-6_s-30\",\n        \"han-fei-zi_ch-45_p-6_s-31\",\n        \"han-fei-zi_ch-45_p-6_s-32\",\n        \"han-fei-zi_ch-45_p-6_s-33\",\n        \"han-fei-zi_ch-45_p-6_s-34\",\n        \"han-fei-zi_ch-45_p-6_s-35\",\n        \"han-fei-zi_ch-45_p-6_s-36\",\n        \"han-fei-zi_ch-45_p-6_s-37\",\n        \"han-fei-zi_ch-45_p-6_s-38\",\n        \"han-fei-zi_ch-45_p-6_s-39\",\n        \"han-fei-zi_ch-45_p-6_s-40\",\n        \"han-fei-zi_ch-45_p-6_s-41\",\n        \"han-fei-zi_ch-45_p-6_s-42\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今家人的治產啊，相忍以飢寒，相強以勞苦，雖犯軍旅的難，饑饉的患，溫衣美食的人或事，必是家啊；相憐以衣食，相惠以佚樂，天饑歲荒，嫁妻賣子的人或事，必是家啊。所以法規法令的為道，前苦而且長利；仁的為道，偷樂而且後窮。聖人權他的輕重，出他的大利，所以用法規法令的相忍，而且棄仁人的相憐啊。學的人或事的言，皆說道：輕刑，此亂亡的督察權術啊。凡賞賜與刑罰的必的人或事，勸禁啊。賞賜厚、則所欲的得啊疾，刑罰重、則所惠的禁啊急。夫欲利的人或事必惡害，害的人或事，利的反啊，反於所欲，焉得無惡。欲治的人或事必惡亂，亂的人或事，治的反啊。正因為如此欲治甚的人或事，他的賞賜必厚矣；他的惡亂甚的人或事，他的刑罰必重矣。今取於輕刑的人或事，他的惡亂不甚啊，他的欲治又不甚啊，此絕不是特無督察權術啊，又乃無行。正因為如此決賢不肖愚知的美，在賞賜與刑罰的輕重。再的人或事況且重刑的人或事，絕不是為罪人啊。明主的法規法令，揆啊。治賊，絕不是治所揆啊；治所揆啊的人或事，是治死人啊。刑盜，絕不是治所刑啊；治所刑啊的人或事，是治胥靡啊。因此韓絕不是子評論說道：重一姦的罪而且止境內的邪，此所以為治啊。重刑罰的人或事，盜賊啊；而且悼懼的人或事，良民啊；欲治的人或事奚疑於重刑！至於談到那厚賞賜的人或事，絕不是獨賞賜功啊，又勸一國。受賞賜的人或事甘利，未賞賜的人或事慕業，是報一人的功而且勸境內的眾啊，欲治的人或事何疑於厚賞賜！今不知治的人或事，皆說道：重刑傷民，輕刑可以止姦，何必於重哉？此不察於治的人或事啊。夫以重止的人或事，未必以輕止啊；以輕止的人或事，必以重止矣。是以上設重刑的人或事而且姦盡止，姦盡止則此奚傷於民啊？所謂重刑的人或事，姦的所利的人或事細，而且上的所加焉的人或事大啊；民不以小利蒙大罪，所以姦必止的人或事啊。所謂輕刑的人或事，姦的所利的人或事大，上的所加焉的人或事小啊；民慕他的利而且傲他的罪，所以姦不止啊。所以先聖有諺說道：不躓於山，而且躓於垤。山的人或事大、所以人順的，垤微小、所以人易的啊。今輕刑刑罰，民必易的。犯而且不誅，是驅國而且棄的啊；犯而且誅的，是為民設陷啊。正因為如此輕罪的人或事，民的垤啊。是以輕罪的為民道啊，絕不是亂國啊則設民陷啊，此則可謂傷民矣！\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈六反〉。韓非深刻融合法、術、勢三大治國精要，此處「今家人之治產也，相忍以飢寒，相強以勞苦，雖犯軍旅之難，饑饉之患，溫衣美食者，必是家也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「今」、「家」、「人」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「今家人之治產也相忍以飢寒相強以勞苦雖犯軍旅之難饑」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「相憐以衣食，相惠以佚樂，天饑歲荒，嫁妻賣子者，必是家也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-7\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"order\": 7,\n      \"canonicalText\": \"今學者皆道書筴之頌語，不察當世之實事，曰：「上不愛民，賦斂常重，則用不足而下恐上，故天下大亂。」此以為足其財用以加愛焉，雖輕刑罰可以治也。此言不然矣。凡人之取重賞罰，固已足之之後也。雖財用足而厚愛之，然而輕刑猶之亂也。夫當家之愛子，財貨足用，財貨足用則輕用，輕用則侈泰；親愛之則不忍，不忍則驕恣；侈泰則家貧，驕恣則行暴，此雖財用足而愛厚，輕利之患也。凡人之生也，財用足則隳於用力，上治懦則肆於為非；財用足而力作者神農也，上治懦而行修者曾、史也；夫民之不及神農、曾、史亦已明矣。老聃有言曰：「知足不辱，知止不殆。」夫以殆辱之故而不求於足之外者老聃也，今以為足民而可以治，是以民為皆如老聃也。故桀貴在天子而不足於尊，富有四海之內而不足於寶。君人者雖足民，不能足使為君，天子而桀未必為天子為足也，則雖足民，何可以為治也？故明主之治國也，適其時事以致財物，論其稅賦以均貧富，厚其爵祿以盡賢能，重其刑罰以禁姦邪，使民以力得富，以事致貴，以過受罪，以功緻賞而不念慈惠之賜，此帝王之政也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-45_p-7_s-1\",\n        \"han-fei-zi_ch-45_p-7_s-2\",\n        \"han-fei-zi_ch-45_p-7_s-3\",\n        \"han-fei-zi_ch-45_p-7_s-4\",\n        \"han-fei-zi_ch-45_p-7_s-5\",\n        \"han-fei-zi_ch-45_p-7_s-6\",\n        \"han-fei-zi_ch-45_p-7_s-7\",\n        \"han-fei-zi_ch-45_p-7_s-8\",\n        \"han-fei-zi_ch-45_p-7_s-9\",\n        \"han-fei-zi_ch-45_p-7_s-10\",\n        \"han-fei-zi_ch-45_p-7_s-11\",\n        \"han-fei-zi_ch-45_p-7_s-12\",\n        \"han-fei-zi_ch-45_p-7_s-13\",\n        \"han-fei-zi_ch-45_p-7_s-14\",\n        \"han-fei-zi_ch-45_p-7_s-15\",\n        \"han-fei-zi_ch-45_p-7_s-16\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今學的人或事皆道書筴的頌語，不察當世的實事，說道：上不愛民，賦斂常重，則用不足而且下恐上，所以天下大亂。此以為足他的財用以加愛焉，雖輕刑刑罰可以治啊。此言不然矣。凡人的取重賞賜與刑罰，固已足的的後啊。雖財用足而且厚愛的，然而且輕刑猶的亂啊。夫當家的愛子，財貨足用，財貨足用則輕用，輕用則侈泰；親愛的則不忍，不忍則驕恣；侈泰則家貧，驕恣則行暴，此雖財用足而且愛厚，輕利的患啊。凡人的生啊，財用足則隳於用力，上治懦則肆於為絕不是；財用足而且力作的人或事神農啊，上治懦而且行修的人或事曾、史啊；夫民的不及神農、曾、史亦已明矣。老聃有言說道：知足不辱，知止不殆。夫以殆辱的所以而且不求於足的外的人或事老聃啊，今以為足民而且可以治，是以民為皆如老聃啊。所以桀貴在天子而且不足於尊，富有四海的內而且不足於寶。國君人的人或事雖足民，不能足使為國君，天子而且桀未必為天子為足啊，則雖足民，何可以為治啊？所以明主的治國啊，適他的時事以致財物，論他的稅賦以均貧富，厚他的爵祿以盡賢能，重他的刑刑罰以禁姦邪，使民以力得富，以事致貴，以過受罪，以功緻賞賜而且不念慈惠的賜，此帝王的政啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈六反〉。韓非深刻融合法、術、勢三大治國精要，此處「今學者皆道書筴之頌語，不察當世之實事，曰：「上不愛民，賦斂常重，則用不足而下恐上，故天下大亂」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「今」、「學」、「皆」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「今學者皆道書筴之頌語不察當世之實事曰上不愛民賦斂」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」此以為足其財用以加愛焉，雖輕刑罰可以治也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-8\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"order\": 8,\n      \"canonicalText\": \"人皆寐、則盲者不知，皆嘿、則喑者不知。覺而使之視，問而使之對，則喑盲者窮矣。不聽其言也，則無術者不知；不任其身也，則不肖者不知；聽其言而求其當，任其身而責其功，則無術不肖者窮矣。夫欲得力士而聽其自言，雖庸人與烏獲不可別也，授之以鼎俎則罷健效矣。故官職者，能士之鼎俎也，任之以事，而愚智分矣。故無術者得於不用，不肖者得於不任，言不用而自文以為辯，身不任而自飾以為高，世主眩其辯、濫其高而尊貴之，是不須視而定明也，不待對而定辯也，喑盲者不得矣。明主聽其言必責其用，觀其行必求其功，然則虛舊之學不談，矜誣之行不飾矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-45_p-8_s-1\",\n        \"han-fei-zi_ch-45_p-8_s-2\",\n        \"han-fei-zi_ch-45_p-8_s-3\",\n        \"han-fei-zi_ch-45_p-8_s-4\",\n        \"han-fei-zi_ch-45_p-8_s-5\",\n        \"han-fei-zi_ch-45_p-8_s-6\",\n        \"han-fei-zi_ch-45_p-8_s-7\",\n        \"han-fei-zi_ch-45_p-8_s-8\",\n        \"han-fei-zi_ch-45_p-8_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"人皆寐、則盲的人或事不知，皆嘿、則喑的人或事不知。覺而且使的視，問而且使的對，則喑盲的人或事窮矣。不聽他的言啊，則無督察權術的人或事不知；不任他的身啊，則不肖的人或事不知；聽他的言而且求他的當，任他的身而且責他的功，則無督察權術不肖的人或事窮矣。夫欲得力士而且聽他的自言，雖庸人與烏獲不可別啊，授的以鼎俎則罷健效矣。所以官職的人或事，能士的鼎俎啊，任的以事，而且愚智分矣。所以無督察權術的人或事得於不用，不肖的人或事得於不任，言不用而且自文以為辯，身不任而且自飾以為高，世主眩他的辯、濫他的高而且尊貴的，是不須視而且定明啊，不待對而且定辯啊，喑盲的人或事不得矣。明主聽他的言必責他的用，觀他的行必求他的功，然則虛舊的學不談，矜誣的行不飾矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈六反〉。韓非深刻融合法、術、勢三大治國精要，此處「人皆寐、則盲者不知，皆嘿、則喑者不知」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「人」、「皆」、「寐」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「人皆寐則盲者不知皆嘿則喑者不知覺而使之視問而使之」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「覺而使之視，問而使之對，則喑盲者窮矣」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"畏死難，降北之民也，而世尊之曰貴生之士；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"學道立方，離法之民也，而世尊之曰文學之士；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"遊居厚養，牟食之民也，而世尊之曰有能之士；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"語曲牟知，偽詐之民也，而世尊之曰辯智之士；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"行劍攻殺，暴憿之民也，而世尊之曰磏勇之士；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 6,\n      \"canonicalText\": \"活湧匿姦，當死之民也，而世尊之曰任譽之士；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 7,\n      \"canonicalText\": \"此六民者，世之所譽也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 8,\n      \"canonicalText\": \"赴險殉誠，死節之民，而世少之曰失計之民也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 9,\n      \"canonicalText\": \"寡聞從令，全法之民也，而世少之曰樸陋之民也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 10,\n      \"canonicalText\": \"力作而食，生利之民也，而世少之曰寡能之民也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 11,\n      \"canonicalText\": \"嘉厚純粹，整穀之民也，而世少之曰愚戇之民也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 12,\n      \"canonicalText\": \"重命畏事，尊上之民也，而世少之曰怯懾之民也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 13,\n      \"canonicalText\": \"挫賊遏姦，明上之民也，而世少之曰諂讒之民也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 14,\n      \"canonicalText\": \"此六民者，世之所毀也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 15,\n      \"canonicalText\": \"姦偽無益之民六，而世譽之如彼；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 16,\n      \"canonicalText\": \"耕戰有益之民六，而世毀之如此；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 17,\n      \"canonicalText\": \"此之謂六反。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-18\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 18,\n      \"canonicalText\": \"布衣循私利而譽之，世主聽虛聲而禮之，禮之所在，利必加焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-19\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 19,\n      \"canonicalText\": \"百姓循私害而訾之，世主壅於俗而賤之，賤之所在，害必加焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-1_s-20\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-1\",\n      \"order\": 20,\n      \"canonicalText\": \"故名賞在乎私惡當罪之民，而毀害在乎公善宜賞之士，索國之富強，不可得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-2_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"古者有諺曰：「為政、猶沐也，雖有棄髮、必為之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-2_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"」愛棄髮之費，而忘長髮之利，不知權者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-2_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"夫彈痤者痛，飲藥者苦，為苦憊之故，不彈痤、飲藥，則身不活、病不已矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-3_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"今上下之接，無子父之澤，而欲以行義禁下，則交必有郤矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-3_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"且父母之於子也，產男則相賀，產女則殺之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-3_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"此俱出父母之懷衽，然男子受賀，女子殺之者，慮其後便、計之長利也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-3_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"故父母之於子也，猶用計算之心以相待也，而況無父子之澤乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-4_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"今學者之說人主也，皆去求利之心，出相愛之道，是求人主之過父母之親也，此不熟於論恩詐而誣也，故明主不受也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-4_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"聖人之治也，審於法禁，法禁明著則官法；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-4_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"必於賞罰，賞罰不阿則民用。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-4_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"官官治則國富，國富則兵強，而霸王之業成矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-4_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"霸王者，人主之大利也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-4_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"人主挾大利以聽治，故其任官者當能，其賞罰無私。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-4_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"使士民明焉盡力致死、則功伐可立而爵祿可致，爵祿致而富貴之業成矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-4_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-4\",\n      \"order\": 8,\n      \"canonicalText\": \"富貴者，人臣之大利也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-4_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-4\",\n      \"order\": 9,\n      \"canonicalText\": \"人臣挾大利以從事，故其行危至死，其力盡而不望。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-4_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-4\",\n      \"order\": 10,\n      \"canonicalText\": \"此謂君不仁，臣不忠，則不可以霸王矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-5_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"夫姦必知則備，必誅則止；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-5_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"不知則肆，不誅則行。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-5_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"夫陳輕貨於幽隱，雖曾、史可疑也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-5_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"懸百金於市，雖大盜不取也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-5_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"不知則曾、史可疑於幽隱，必知則大盜不取懸金於市。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-5_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-5\",\n      \"order\": 6,\n      \"canonicalText\": \"故明主之治國也眾其守、而重其罪，使民以法禁而不以廉止。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-5_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-5\",\n      \"order\": 7,\n      \"canonicalText\": \"母之愛子也倍父，父令之行於子者十母；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-5_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-5\",\n      \"order\": 8,\n      \"canonicalText\": \"吏之於民無愛，令之行於民也萬父。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-5_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-5\",\n      \"order\": 9,\n      \"canonicalText\": \"母積愛而令窮，吏用威嚴而民聽從，嚴愛之筴亦可決矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-5_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-5\",\n      \"order\": 10,\n      \"canonicalText\": \"且父母之所以求於子也，動作則欲其安利也，行身則欲其遠罪也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-5_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-5\",\n      \"order\": 11,\n      \"canonicalText\": \"君上之於民也，有難則用其死，安平則盡其力。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-5_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-5\",\n      \"order\": 12,\n      \"canonicalText\": \"親以厚愛關子於安利而不聽，君以無愛利求民之死力而令行。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-5_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-5\",\n      \"order\": 13,\n      \"canonicalText\": \"明主知之，故不養恩愛之心而增威嚴之勢。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-5_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-5\",\n      \"order\": 14,\n      \"canonicalText\": \"故母厚愛處，子多敗，推愛也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-5_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-5\",\n      \"order\": 15,\n      \"canonicalText\": \"父薄愛教笞，子多善，用嚴也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"今家人之治產也，相忍以飢寒，相強以勞苦，雖犯軍旅之難，饑饉之患，溫衣美食者，必是家也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"相憐以衣食，相惠以佚樂，天饑歲荒，嫁妻賣子者，必是家也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"故法之為道，前苦而長利；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"仁之為道，偷樂而後窮。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"聖人權其輕重，出其大利，故用法之相忍，而棄仁人之相憐也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"學者之言，皆曰輕刑，此亂亡之術也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"凡賞罰之必者，勸禁也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 8,\n      \"canonicalText\": \"賞厚、則所欲之得也疾，罰重、則所惠之禁也急。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 9,\n      \"canonicalText\": \"夫欲利者必惡害，害者，利之反也，反於所欲，焉得無惡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 10,\n      \"canonicalText\": \"欲治者必惡亂，亂者，治之反也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 11,\n      \"canonicalText\": \"是故欲治甚者，其賞必厚矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 12,\n      \"canonicalText\": \"其惡亂甚者，其罰必重矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 13,\n      \"canonicalText\": \"今取於輕刑者，其惡亂不甚也，其欲治又不甚也，此非特無術也，又乃無行。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 14,\n      \"canonicalText\": \"是故決賢不肖愚知之美，在賞罰之輕重。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 15,\n      \"canonicalText\": \"且夫重刑者，非為罪人也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 16,\n      \"canonicalText\": \"明主之法，揆也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 17,\n      \"canonicalText\": \"治賊，非治所揆也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-18\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 18,\n      \"canonicalText\": \"治所揆也者，是治死人也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-19\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 19,\n      \"canonicalText\": \"刑盜，非治所刑也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-20\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 20,\n      \"canonicalText\": \"治所刑也者，是治胥靡也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-21\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 21,\n      \"canonicalText\": \"故曰重一姦之罪而止境內之邪，此所以為治也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-22\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 22,\n      \"canonicalText\": \"重罰者，盜賊也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-23\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 23,\n      \"canonicalText\": \"而悼懼者，良民也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-24\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 24,\n      \"canonicalText\": \"欲治者奚疑於重刑！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-25\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 25,\n      \"canonicalText\": \"若夫厚賞者，非獨賞功也，又勸一國。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-26\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 26,\n      \"canonicalText\": \"受賞者甘利，未賞者慕業，是報一人之功而勸境內之眾也，欲治者何疑於厚賞！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-27\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 27,\n      \"canonicalText\": \"今不知治者，皆曰重刑傷民，輕刑可以止姦，何必於重哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-28\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 28,\n      \"canonicalText\": \"此不察於治者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-29\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 29,\n      \"canonicalText\": \"夫以重止者，未必以輕止也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-30\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 30,\n      \"canonicalText\": \"以輕止者，必以重止矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-31\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 31,\n      \"canonicalText\": \"是以上設重刑者而姦盡止，姦盡止則此奚傷於民也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-32\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 32,\n      \"canonicalText\": \"所謂重刑者，姦之所利者細，而上之所加焉者大也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-33\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 33,\n      \"canonicalText\": \"民不以小利蒙大罪，故姦必止者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-34\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 34,\n      \"canonicalText\": \"所謂輕刑者，姦之所利者大，上之所加焉者小也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-35\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 35,\n      \"canonicalText\": \"民慕其利而傲其罪，故姦不止也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-36\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 36,\n      \"canonicalText\": \"故先聖有諺曰：「不躓於山，而躓於垤。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-37\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 37,\n      \"canonicalText\": \"」山者大、故人順之，垤微小、故人易之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-38\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 38,\n      \"canonicalText\": \"今輕刑罰，民必易之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-39\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 39,\n      \"canonicalText\": \"犯而不誅，是驅國而棄之也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-40\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 40,\n      \"canonicalText\": \"犯而誅之，是為民設陷也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-41\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 41,\n      \"canonicalText\": \"是故輕罪者，民之垤也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-6_s-42\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-6\",\n      \"order\": 42,\n      \"canonicalText\": \"是以輕罪之為民道也，非亂國也則設民陷也，此則可謂傷民矣！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-7_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"今學者皆道書筴之頌語，不察當世之實事，曰：「上不愛民，賦斂常重，則用不足而下恐上，故天下大亂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-7_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"」此以為足其財用以加愛焉，雖輕刑罰可以治也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-7_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"此言不然矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-7_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"凡人之取重賞罰，固已足之之後也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-7_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-7\",\n      \"order\": 5,\n      \"canonicalText\": \"雖財用足而厚愛之，然而輕刑猶之亂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-7_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-7\",\n      \"order\": 6,\n      \"canonicalText\": \"夫當家之愛子，財貨足用，財貨足用則輕用，輕用則侈泰；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-7_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-7\",\n      \"order\": 7,\n      \"canonicalText\": \"親愛之則不忍，不忍則驕恣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-7_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-7\",\n      \"order\": 8,\n      \"canonicalText\": \"侈泰則家貧，驕恣則行暴，此雖財用足而愛厚，輕利之患也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-7_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-7\",\n      \"order\": 9,\n      \"canonicalText\": \"凡人之生也，財用足則隳於用力，上治懦則肆於為非；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-7_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-7\",\n      \"order\": 10,\n      \"canonicalText\": \"財用足而力作者神農也，上治懦而行修者曾、史也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-7_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-7\",\n      \"order\": 11,\n      \"canonicalText\": \"夫民之不及神農、曾、史亦已明矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-7_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-7\",\n      \"order\": 12,\n      \"canonicalText\": \"老聃有言曰：「知足不辱，知止不殆。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-7_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-7\",\n      \"order\": 13,\n      \"canonicalText\": \"」夫以殆辱之故而不求於足之外者老聃也，今以為足民而可以治，是以民為皆如老聃也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-7_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-7\",\n      \"order\": 14,\n      \"canonicalText\": \"故桀貴在天子而不足於尊，富有四海之內而不足於寶。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-7_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-7\",\n      \"order\": 15,\n      \"canonicalText\": \"君人者雖足民，不能足使為君，天子而桀未必為天子為足也，則雖足民，何可以為治也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-7_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-7\",\n      \"order\": 16,\n      \"canonicalText\": \"故明主之治國也，適其時事以致財物，論其稅賦以均貧富，厚其爵祿以盡賢能，重其刑罰以禁姦邪，使民以力得富，以事致貴，以過受罪，以功緻賞而不念慈惠之賜，此帝王之政也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-8_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"人皆寐、則盲者不知，皆嘿、則喑者不知。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-8_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"覺而使之視，問而使之對，則喑盲者窮矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-8_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"不聽其言也，則無術者不知；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-8_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"不任其身也，則不肖者不知；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-8_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"聽其言而求其當，任其身而責其功，則無術不肖者窮矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-8_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-8\",\n      \"order\": 6,\n      \"canonicalText\": \"夫欲得力士而聽其自言，雖庸人與烏獲不可別也，授之以鼎俎則罷健效矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-8_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-8\",\n      \"order\": 7,\n      \"canonicalText\": \"故官職者，能士之鼎俎也，任之以事，而愚智分矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-8_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-8\",\n      \"order\": 8,\n      \"canonicalText\": \"故無術者得於不用，不肖者得於不任，言不用而自文以為辯，身不任而自飾以為高，世主眩其辯、濫其高而尊貴之，是不須視而定明也，不待對而定辯也，喑盲者不得矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-45_p-8_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-45\",\n      \"passageId\": \"han-fei-zi_ch-45_p-8\",\n      \"order\": 9,\n      \"canonicalText\": \"明主聽其言必責其用，觀其行必求其功，然則虛舊之學不談，矜誣之行不飾矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
